/* Cooling selections use individual fans, regardless of retail pack size. */
const fanLayouts=(()=>{try{return (new URL(location.href).searchParams.get('fans')||'').split('|').filter(Boolean).map(v=>{const [position,flow]=v.split(':');return{position:['top','front','rear','side','bottom'].includes(position)?position:'top',flow:flow==='intake'?'intake':'exhaust'}})}catch{return[]}})();
function fanPlacement(index,part){const choice=fanLayouts[index]||{position:'top',flow:'exhaust'},chassis=buildPart('case'),mounts=chassis?.physical?.mounts,diameter=part.specs['Fan size'];if(!chassis)return{...choice,fit:false,state:'unknown',reason:'Choose a case to place this fan.'};if(!mounts)return{...choice,fit:false,state:'unknown',reason:'Fan mounts have not been researched for this case.'};const capacity=mounts[choice.position]?.[diameter];if(!capacity)return{...choice,fit:false,state:'fail',reason:`No documented ${diameter} mm ${choice.position} mount.`};const group=buildParts('fan').map((p,i)=>({p,i})).filter(x=>(fanLayouts[x.i]?.position||'top')===choice.position);if(group.some(x=>x.p.specs['Fan size']!==diameter))return{...choice,fit:false,state:'unknown',reason:'Mixed fan sizes in one mounting zone need manual verification.'};if(group.length>capacity)return{...choice,fit:false,state:'fail',reason:`${choice.position}: ${group.length} fans selected; ${capacity} supported at ${diameter} mm.`};return{...choice,fit:true,state:'pass',reason:`${diameter} mm ${choice.position} mount listed. Thickness, radiator and cable clearance still need checking.`,ordinal:group.findIndex(x=>x.i===index)};}
const basePlacement=partPlacement;partPlacement=function(slot,index,part,analysis){return slot==='fan'?fanPlacement(index,part):basePlacement(slot,index,part,analysis)};
const baseAnalysis=analyzeBuild;analyzeBuild=function(){const a=baseAnalysis();for(const [i,p]of buildParts('fan').entries()){const f=fanPlacement(i,p);a.checks.push(checkResult(f.state,`Fan ${i+1}: ${p.name}`,f.reason))}const chassis=buildPart('case'),psu=buildPart('psu');if(chassis?.physical?.psuFormats&&psu){const format=psu.id==='rm850x'?'ATX':/SFX-L/i.test(psu.architecture)?'SFX-L':/SFX/i.test(psu.architecture)?'SFX':/ATX/i.test(psu.architecture)?'ATX':null;a.checks.push(checkResult(!format?'unknown':chassis.physical.psuFormats.includes(format)?'pass':'fail','Power supply format',format?`${format} supply; case supports ${chassis.physical.psuFormats.join(' / ')}.`:'Power supply form factor is not indexed.'))}if(a.checks.some(c=>c.state==='fail'))a.verdict='fail';else if(a.checks.some(c=>c.state==='unknown'))a.verdict='unknown';return a};
function renderFanControls(){const row=document.querySelector('[data-builder-row=fan]');if(!row)return;row.querySelector('.fan-layouts')?.remove();const entries=buildInstances('fan');if(!entries.length)return;const panel=document.createElement('div');panel.className='fan-layouts';panel.innerHTML='<h3>Fan placement</h3><p>Quantities below are individual fans. A multipack is not added automatically.</p>'+entries.map(({part},i)=>{const f=fanPlacement(i,part);return `<fieldset><legend>${i+1}. ${escapeHTML(part.name)}</legend><label>Mounting position<select data-fan-position="${i}" aria-label="Fan ${i+1} position">${['top','front','rear','side','bottom'].map(v=>`<option ${v===f.position?'selected':''}>${v}</option>`).join('')}</select></label><label>Airflow<select data-fan-flow="${i}" aria-label="Fan ${i+1} airflow"><option value="exhaust" ${f.flow==='exhaust'?'selected':''}>Exhaust — out of case</option><option value="intake" ${f.flow==='intake'?'selected':''}>Intake — into case</option></select></label><p class="fan-fit ${f.state}">${escapeHTML(f.reason)}</p><small>${escapeHTML(part.physical?.connector||'Check manufacturer connection requirements.')}${part.physical?.reverse?' · Reverse blades':''}${part.physical?.swappable?' · Swappable impeller':''}</small></fieldset>`}).join('');row.append(panel)}
document.addEventListener('change',e=>{if(e.target.dataset.fanPosition!==undefined||e.target.dataset.fanFlow!==undefined){const index=Number(e.target.dataset.fanPosition??e.target.dataset.fanFlow),f=fanLayouts[index]||{position:'top',flow:'exhaust'};if(e.target.dataset.fanPosition!==undefined)f.position=e.target.value;else f.flow=e.target.value;fanLayouts[index]=f;const url=new URL(location.href);url.searchParams.set('fans',buildParts('fan').map((_,i)=>`${fanLayouts[i]?.position||'top'}:${fanLayouts[i]?.flow||'exhaust'}`).join('|'));history.replaceState(null,'',url);renderBuilder()}});
document.addEventListener('pcp:build',renderFanControls);renderBuilder();
